1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface QuoteStep {
11	  op: "quote";
12	  items: Item[];
13	}
14	
15	export interface Item {
16	  type: string;
17	  material?: string;
18	  enchantment?: number;
19	  cursed?: boolean;
20	}
21	
22	export interface Damage {
23	  itemType: string;
24	  amount: number;
25	}
26	
27	export interface Incident {
28	  cause: string;
29	  damages: Damage[];
30	}
31	
32	export interface ClaimStep {
33	  op: "claim";
34	  policy: number;
35	  incident: Incident;
36	}
37	
38	export type Step = QuoteStep | ClaimStep;
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const sumBy = <T>(values: T[], amountOf: (value: T) => number): number =>
56	  values.reduce((total, value) => total + amountOf(value), 0);
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const itemBasePremium = (item: Item): number => {
68	  const basePremium = BASE_PREMIUM_BY_TYPE[item.type];
69	  if (basePremium === undefined) {
70	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
71	  }
72	  return basePremium;
73	};
74	
75	const BLOCK_SIZE = 3;
76	
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	// The block branch does not consult itemBasePremium, but that does not let an
80	// unknown type through: quotePremium sums itemSurcharge over every item, and
81	// that path calls itemBasePremium unconditionally. Exactly three broomsticks
82	// are rejected there, not here.
83	const basePremiumForSameTypeItems = (items: Item[]): number =>
84	  items.length === BLOCK_SIZE
85	    ? BLOCK_BASE_PREMIUM
86	    : sumBy(items, itemBasePremium);
87	
88	const sameTypeGroups = (items: Item[]): Item[][] => {
89	  const groupsByType = new Map<string, Item[]>();
90	  for (const item of items) {
91	    const group = groupsByType.get(item.type) ?? [];
92	    group.push(item);
93	    groupsByType.set(item.type, group);
94	  }
95	  return [...groupsByType.values()];
96	};
97	
98	const CURSE_SURCHARGE_RATE = 0.5;
99	
100	const HIGH_ENCHANTMENT_LEVEL = 5;
101	
102	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
103	
104	interface SurchargeRule {
105	  appliesTo: (item: Item) => boolean;
106	  rate: number;
107	}
108	
109	const SURCHARGE_RULES: SurchargeRule[] = [
110	  {
111	    appliesTo: (item) => item.cursed === true,
112	    rate: CURSE_SURCHARGE_RATE,
113	  },
114	  {
115	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
116	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
117	  },
118	];
119	
120	const itemSurchargeRate = (item: Item): number =>
121	  sumBy(
122	    SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)),
123	    (rule) => rule.rate,
124	  );
125	
126	const itemSurcharge = (item: Item): number =>
127	  itemBasePremium(item) * itemSurchargeRate(item);
128	
129	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
130	
131	const PROCESSING_FEE = 5;
132	
133	const LOYALTY_YEARS = 2;
134	
135	const LOYALTY_DISCOUNT_RATE = 0.2;
136	
137	const loyaltyDiscountRate = (customer: Customer): number =>
138	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT_RATE : 0;
139	
140	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
141	
142	const followUpContractDiscountRate = (precedingContracts: number): number =>
143	  precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
144	
145	// Policy-wide modifiers are rates applied to the policy base premium.
146	// Surcharges are positive rates, discounts negative ones.
147	const policyModifierRate = (
148	  customer: Customer,
149	  precedingContracts: number,
150	): number =>
151	  FIRST_INSURANCE_SURCHARGE_RATE +
152	  loyaltyDiscountRate(customer) +
153	  followUpContractDiscountRate(precedingContracts);
154	
155	const quotePremium = (
156	  step: QuoteStep,
157	  customer: Customer,
158	  precedingContracts: number,
159	): number => {
160	  const policyBasePremium = sumBy(
161	    sameTypeGroups(step.items),
162	    basePremiumForSameTypeItems,
163	  );
164	  const itemSurcharges = sumBy(step.items, itemSurcharge);
165	  // Keep this as `base + base * rate`. Factoring it to `base * (1 + rate)`
166	  // introduces IEEE-754 drift that is always upward (e.g. base 180 at rate 0.1
167	  // gives 198.00000000000003 instead of 198), and Math.ceil below turns any
168	  // such drift into a full extra G. Sword + staff would quote 204, not 203.
169	  const policyModifierAmount =
170	    policyBasePremium * policyModifierRate(customer, precedingContracts);
171	  // Rounded in the MHPCO's favour; only the final premium is rounded.
172	  return Math.ceil(
173	    policyBasePremium + itemSurcharges + policyModifierAmount + PROCESSING_FEE,
174	  );
175	};
176	
177	// Deliberately kept separate from BASE_PREMIUM_BY_TYPE. The two tables share a
178	// key domain but not a fact: an item's base premium and its insurance value are
179	// independent numbers the spec states separately. Merging them into one
180	// catalogue would couple them in the reader's mind for no gain.
181	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
182	  sword: 1000,
183	  amulet: 600,
184	  staff: 800,
185	  potion: 400,
186	  rune: 250,
187	  moonstone: 250,
188	};
189	
190	// Named for symmetry with itemBasePremium: both are per-item lookups that
191	// reject an unknown type rather than returning undefined.
192	//
193	// No input reaches this with an unknown type today — a quote rejects one via
194	// itemSurcharge -> itemBasePremium, and a claim rejects one via insuredItemFor
195	// — so the throw is unreachable by any current test. It is here because the
196	// declared `number` return would otherwise be a lie: indexing a
197	// Record<string, number> yields `number | undefined` at runtime, and an
198	// undefined would silently poison the insurance sum with NaN rather than fail.
199	const itemInsuranceValue = (item: Item): number => {
200	  const insuranceValue = INSURANCE_VALUE_BY_TYPE[item.type];
201	  if (insuranceValue === undefined) {
202	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
203	  }
204	  return insuranceValue;
205	};
206	
207	// The block discount affects the premium only, never the insurance sum.
208	const insuranceSum = (policy: QuoteStep): number =>
209	  sumBy(policy.items, itemInsuranceValue);
210	
211	const DEDUCTIBLE = 100;
212	
213	const CAP_MULTIPLE = 2;
214	
215	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
216	
217	const REDUCED_REIMBURSEMENT_RATE = 0.5;
218	
219	const FULL_REIMBURSEMENT_RATE = 1;
220	
221	// Named for the trigger (enchantment level), to keep it distinct from the
222	// premium-side HIGH_ENCHANTMENT_LEVEL, which is a different threshold (5).
223	const reimbursementRate = (item: Item): number =>
224	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
225	    ? REDUCED_REIMBURSEMENT_RATE
226	    : FULL_REIMBURSEMENT_RATE;
227	
228	// The deductible is withheld once per damage entry, not once per incident,
229	// and applies after any reimbursement clause has reduced the amount.
230	// Clamped per entry, not on the total: a damage smaller than the deductible
231	// yields nothing, but must not eat into another damage's reimbursement.
232	const payableForDamage = (damage: Damage, item: Item): number => {
233	  const reimbursement = damage.amount * reimbursementRate(item);
234	  return Math.max(0, reimbursement - DEDUCTIBLE);
235	};
236	
237	// Which insured item a damage entry refers to. An unknown item type is
238	// rejected here too: it is simply a type the policy does not cover.
239	const insuredItemFor = (damage: Damage, policy: QuoteStep): Item => {
240	  const insured = policy.items.find((item) => item.type === damage.itemType);
241	  if (insured === undefined) {
242	    throw new Error(
243	      `The policy does not cover an item of type "${damage.itemType}"`,
244	    );
245	  }
246	  return insured;
247	};
248	
249	// Kept separate from sameTypeGroups, which groups the items themselves and
250	// discards the type key. This one needs the key, to look a type up; that one
251	// needs the members, to price a block. Merging them would distort whichever
252	// call site did not ask for the shape.
253	const countByType = <T>(
254	  values: T[],
255	  typeOf: (value: T) => string,
256	): Map<string, number> => {
257	  const counts = new Map<string, number>();
258	  for (const value of values) {
259	    const type = typeOf(value);
260	    counts.set(type, (counts.get(type) ?? 0) + 1);
261	  }
262	  return counts;
263	};
264	
265	// Distinct from the zero-clamp in payableForDamage: that handles a legitimate
266	// damage too small to clear the deductible, whereas a negative amount is not a
267	// damage at all.
268	const rejectNegativeAmounts = (damages: Damage[]): void => {
269	  for (const damage of damages) {
270	    if (damage.amount < 0) {
271	      throw new Error(
272	        `A damage amount cannot be negative, but the claim reports ${damage.amount}`,
273	      );
274	    }
275	  }
276	};
277	
278	// A damage entry is one damaged item, so a type cannot be damaged more times
279	// than the policy insures it. Checked per type across the whole incident before
280	// any settlement, because the spec rejects the claim as a whole.
281	const rejectOverClaimedTypes = (damages: Damage[], policy: QuoteStep): void => {
282	  const insuredCounts = countByType(policy.items, (item) => item.type);
283	  for (const [type, damagedCount] of countByType(
284	    damages,
285	    (damage) => damage.itemType,
286	  )) {
287	    if (damagedCount > (insuredCounts.get(type) ?? 0)) {
288	      throw new Error(
289	        `The policy covers fewer items of type "${type}" than the claim reports damaged`,
290	      );
291	    }
292	  }
293	};
294	
295	const policyCap = (policy: QuoteStep): number =>
296	  insuranceSum(policy) * CAP_MULTIPLE;
297	
298	// The cap is a per-policy budget: a claim pays out at most what is left of it.
299	const settleClaim = (
300	  step: ClaimStep,
301	  policy: QuoteStep,
302	  capRemaining: number,
303	): ClaimResult => {
304	  rejectNegativeAmounts(step.incident.damages);
305	  rejectOverClaimedTypes(step.incident.damages, policy);
306	  const payable = sumBy(step.incident.damages, (damage) =>
307	    payableForDamage(damage, insuredItemFor(damage, policy)),
308	  );
309	  // Rounded in the MHPCO's favour — down, the opposite of the premium's
310	  // Math.ceil. Only the final payout is rounded, and the cap is decremented by
311	  // the rounded figure so the remaining cap stays in whole G.
312	  const payout = Math.floor(Math.min(payable, capRemaining));
313	  return { payout, remainingCap: capRemaining - payout };
314	};
315	
316	export const runScenario = (scenario: Scenario): ScenarioResult => {
317	  const results: StepResult[] = [];
318	  const capRemainingByPolicy = new Map<number, number>();
319	  // Only quote steps conclude a contract, so this cannot be derived from the
320	  // step index: a claim step must not earn the next quote its follow-up
321	  // discount. Incremented after pricing, so during a quote it holds the number
322	  // of contracts concluded *before* that quote — hence `preceding`.
323	  let precedingContracts = 0;
324	  for (const step of scenario.steps) {
325	    if (step.op === "quote") {
326	      results.push({
327	        premium: quotePremium(step, scenario.customer, precedingContracts),
328	      });
329	      precedingContracts += 1;
330	    } else {
331	      const policy = scenario.steps[step.policy] as QuoteStep;
332	      const capRemaining =
333	        capRemainingByPolicy.get(step.policy) ?? policyCap(policy);
334	      const result = settleClaim(step, policy, capRemaining);
335	      capRemainingByPolicy.set(step.policy, result.remainingCap);
336	      results.push(result);
337	    }
338	  }
339	  return { results };
340	};
